import{_ as p,a0 as l,w as s,s as a,ao as i,I as r,x as e,a1 as n,A as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"每日 Ubuntu 小技巧——以色辨夾 | LCTT x X-CMD","titleTemplate":false,"description":"每日 Ubuntu 小技巧——以色辨夾 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日 Ubuntu 小技巧——以色辨夾 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日 Ubuntu 小技巧——以色辨夾 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/Daily Ubuntu Tips – Identify Folders By Colors In Ubuntu","title":"每日 Ubuntu 小技巧——以色辨夾","tag":"201405","desc":""},"relativePath":"201405/Daily Ubuntu Tips – Identify Folders By Colors In Ubuntu.md","filePath":"[post].md"}'),d={name:"201405/Daily Ubuntu Tips – Identify Folders By Colors In Ubuntu.md"};function b(f,t,m,T,C,g){const o=l("Link");return s(),a("div",null,[t[11]||(t[11]=i(`<h1 id="每日-ubuntu-小技巧——以色辨夾" tabindex="-1">每日 Ubuntu 小技巧——以色辨夾 <a class="header-anchor" href="#每日-ubuntu-小技巧——以色辨夾" aria-label="Permalink to “每日 Ubuntu 小技巧——以色辨夾”">​</a></h1><p>這篇簡短的文章將教會你如何在Ubuntu 14.04或者其先前版本中使用美化工具來實現通過顏色分辨文件夾。這個工具就是<strong>Folder Color</strong>,它允許用户改變 Nautilus 文件瀏覽器中文件夾的顏色，這樣就可以讓用户很容易地識別並區分它們。</p><p>這個工具的開發者設計初衷是與 Nautilus 配合使用，其實它也可以與Ubuntu上其它的圖標主題配合使用。這是一個很好的工具，輕量級，不會影響你的系統的性能。</p><p>這個軟件安裝起來方便，讓下面這個簡短的教程告訴你如何做吧。</p><p>假如你想將重要的文件夾設置成紅色的，或者將文檔文件夾設置為黃色，你可以用Folder Color輕鬆地更改它們的顏色。</p><p>接下來教你來安裝這個工具。</p><p>在Ubuntu 中<strong>Ctrl - Alt - T</strong>打開終端。添加下面的PPA源。</p><pre><code>sudo add-apt-repository ppa:costales/folder-color
</code></pre><p>然後運行下面的命令更新你的系統並安裝Folder Color。</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get install folder-color
</code></pre><p>這樣安裝就可以了。現在你要做的就是註銷登錄然後再次登入系統或者重新啓動Nautilus 。打開Nautilus，在你想改變顏色的文件夾上右鍵單擊選擇你想要的顏色。這些是預先定義的顏色，或許無法滿足你的需要，但是對於大多數用户來説這足夠了。</p><p>如果你想卸載它，運行下面的命令移除PPA源。</p><pre><code>sudo add-apt-repository -r ppa:costales/folder-color
</code></pre><p>最後，運行下面的命令移除Folder Color 。</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get remove folder-color
</code></pre><p>使用愉快！</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/04/foldercolorubuntu.png" alt=""></p><hr>`,18)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),n(o,{href:"http://www.liberiangeek.net/2014/04/daily-ubuntu-tips-identify-folders-by-colors-in-ubuntu/"},{default:u(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2014/04/daily-ubuntu-tips-identify-folders-by-colors-in-ubuntu/",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=e("譯者：",-1)),n(o,{href:"https://github.com/Linchenguang"},{default:u(()=>[...t[2]||(t[2]=[e("Linchenguang",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),n(o,{href:"https://github.com/carolinewuyan"},{default:u(()=>[...t[3]||(t[3]=[e("Caroline",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),n(o,{href:"http://linux.cn/"},{default:u(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const w=p(d,[["render",b]]);export{_ as __pageData,w as default};
